SELECT 
FROM TBL_DATA_ANALYSIS_TASKS


        AND ORGID = #{params.orgId}


        AND TASKNO LIKE CONCAT('%', #{params.taskNo}, '%')


        AND TASKNAME LIKE CONCAT('%', #{params.taskName}, '%')


        AND TASKTYPE = #{params.taskType}


        AND ANALYSISTYPE = #{params.analysisType}


        AND TASKSTATUS = #{params.taskStatus}


        AND SCHEDULETYPE = #{params.scheduleType}


        AND DATASOURCE LIKE CONCAT('%', #{params.dataSource}, '%')


        AND MODELID = #{params.modelId}


        AND EXECUTEUSER = #{params.executeUser}


        AND CREATETIME >= #{params.startDate}


        AND CREATETIME <= #{params.endDate}


ORDER BY CREATETIME DESC

SELECT 
FROM TBL_DATA_ANALYSIS_TASKS
WHERE TASKNO = #{taskNo} AND ORGID = #{orgId}

SELECT COUNT(1) > 0
FROM TBL_DATA_ANALYSIS_TASKS
WHERE TASKNO = #{taskNo} AND ORGID = #{orgId}

SELECT 
FROM TBL_DATA_ANALYSIS_TASKS
WHERE TASKSTATUS = 'COMPLETED' AND ORGID = #{orgId}

    AND ENDTIME >= #{startDate}


    AND ENDTIME <= #{endDate}

ORDER BY ENDTIME DESC

