DELETE FROM TBL_DATA_ANALYSIS_TASKS
WHERE CREATETIME < #{expiredDate} 
AND ORGID = #{orgId}
AND TASKSTATUS IN ('COMPLETED', 'FAILED', 'CANCELLED')

