SELECT COUNT(*) as totalTasks, SUM(CASE WHEN TASKSTATUS = 'PENDING' THEN 1 ELSE 0 END) as pendingTasks, SUM(CASE WHEN TASKSTATUS = 'RUNNING' THEN 1 ELSE 0 END) as runningTasks, SUM(CASE WHEN TASKSTATUS = 'COMPLETED' THEN 1 ELSE 0 END) as completedTasks, SUM(CASE WHEN TASKSTATUS = 'FAILED' THEN 1 ELSE 0 END) as failedTasks, SUM(CASE WHEN TASKSTATUS = 'CANCELLED' THEN 1 ELSE 0 END) as cancelledTasks FROM TBL_DATA_ANALYSIS_TASKS WHERE ORGID = #{orgId}
AND CREATETIME >= #{startDate}
AND CREATETIME <= #{endDate}

SELECT AVG(EXECUTIONTIME) as avgExecutionTime, MIN(EXECUTIONTIME) as minExecutionTime, MAX(EXECUTIONTIME) as maxExecutionTime, SUM(EXECUTIONTIME) as totalExecutionTime FROM TBL_DATA_ANALYSIS_TASKS WHERE ORGID = #{orgId} AND TASKSTATUS = 'COMPLETED' AND EXECUTIONTIME IS NOT NULL
AND ENDTIME >= #{startDate}
AND ENDTIME <= #{endDate}

